/** Authored close inquiry for the separate demo; grounds name exact reading
 * units. Comparisons are argued here, without changing source or canon status. */
const b = (ru, en) => ({ ru, en });
const g = (ref, ru, en) => ({ ref, focus: b(ru, en) });
const q = (argument, grounds, question, extra = {}) => ({ argument, grounds, ...(question ? { question } : {}), ...extra });

export const INQUIRY_READINGS_ECHOES = {
  'demo:spinoza': q(
    b('В I, определении 7, Спиноза различает две необходимости по тому, откуда определяется существование и действие вещи. Свободное существует из собственной природы и определяется собой; принуждённое определяется другим к определённому способу существования и действия. Поэтому отсутствие причин не входит в определение свободы: решающей становится необходимость собственной природы. Этот ход меняет сам предмет спора о свободе — с возможности произвольно прервать порядок на способ определения действующего.',
      'In I, definition 7, Spinoza distinguishes two necessities by what determines a thing’s existence and action. What is free exists through its own nature and determines itself; what is constrained is determined by another to a definite way of existing and acting. An absence of causes therefore does not belong to the definition of freedom: the necessity of one’s own nature is decisive. This changes the subject of the dispute about freedom from arbitrarily interrupting an order to the manner in which the agent is determined.'),
    [g('spinoza1d7', 'Два предложения определения прямо противопоставляют необходимость собственной природы определению извне; второе уточняет «необходимое» словом «принуждённое».', 'The definition’s two sentences directly contrast the necessity of one’s own nature with external determination; the second qualifies “necessary” as “constrained”.')],
    b('Почему Спинозе требуется уточнение «или, лучше, принуждённое», если необходимость уже присутствует в определении свободного?', 'Why does Spinoza need the qualification “or rather constrained” when necessity already appears in the definition of freedom?')),

  'demo:epictetus': q(
    b('В первом разделе «Энхиридиона» граница проходит не между большим и малым влиянием, а между собственными суждениями, стремлениями и тем, что не принадлежит собственной деятельности. Тело, имущество, известность и должность помещены по другую сторону этой границы. Обещанная свобода от принуждения поэтому связана с переменой того, что человек считает своим, а не с усилением власти над обстоятельствами. Следующее наставление раскрывает цену: стремясь также к богатству и власти, можно не добиться их и заведомо упустить то, посредством чего достигаются свобода и счастье. Проверка впечатления в конце раздела возвращает общую границу к отдельному случаю суждения.',
      'In the Enchiridion’s first section, the boundary runs not between greater and lesser influence but between one’s own judgments and impulses and what does not belong to one’s own activity. Body, property, reputation and office are placed on the other side. The promised freedom from constraint is therefore connected with changing what one regards as one’s own rather than increasing power over circumstances. The following instruction reveals the cost: also seeking wealth and power may fail to obtain them and will certainly forfeit what brings freedom and happiness. The examination of an impression at the section’s end brings the general boundary back to a particular act of judgment.'),
    [g('epictetus1', 'Первое перечисление задаёт границу; затем обещание непринуждённости связано с отказом присваивать чужое, предупреждением о богатстве и власти и заключительной проверкой впечатления.', 'The opening list establishes the boundary; the promise of freedom from constraint is then connected with not claiming what belongs to others, the warning about wealth and power, and the concluding examination of an impression.')],
    b('Что изменилось бы в доводе, если заменить «принадлежит нам» на «поддаётся нашему влиянию»?', 'What would change in the argument if “belongs to us” were replaced with “can be influenced by us”?')),

  'demo:joy-pain': q(
    b('В «Выздоравливающем» Заратустра связывает худшее в человеке с возможностью лучшего, но переживает отвращение к возвращению малого. В четвёртой «Печати» радость и скорбь, добро и зло входят в образ смеси, которой утверждение сообщает единство. Здесь боль не выступает заранее установленной последней мерой ценности: требуется понять сам переход от отвращения к утверждению. Главы «О сострадательных» и «Знамение» уточняют эту трудность: создающая любовь ставится выше жалости, а сострадание к высшим людям оказывается последним искушением Заратустры перед возвращением к своему делу. Чтение этих мест спрашивает, каким образом меняется оценка страдания внутри движения книги.',
      'In “The Convalescent”, Zarathustra connects what is worst in humans with the possibility of what is best, yet experiences nausea at the small human’s return. In the fourth “Seal”, joy and sorrow, good and evil enter an image of mixture to which affirmation gives unity. Pain is not an already established final measure of value here: the transition from nausea to affirmation itself needs understanding. “The Pitiful” and “The Sign” sharpen this difficulty: creating love is placed above pity, while fellow-suffering with the higher men becomes Zarathustra’s last temptation before returning to his work. Reading these passages asks how suffering’s evaluation changes within the book’s movement.'),
    [g('z-convalescent', 'Заратустра сначала утверждает необходимость худшего для лучшего, затем называет возвращение малого причиной отвращения.', 'Zarathustra first affirms the necessity of the worst for the best, then names the small human’s return as the cause of his nausea.'),
     g('z-seven-seals', '§4: смесь радости и скорби, добра и зла ведёт к повторяющемуся признанию любви вечности.', 'Section 4: the mixture of joy and sorrow, good and evil leads to the recurring declaration of love for eternity.'),
     g('z-pitiful', 'Заключение: великая любовь превосходит жалость, поскольку стремится создать любимое; этому предшествует образ помощи страдающему другу как жёсткого ложа.', 'Conclusion: great love exceeds pity because it seeks to create what is loved; this follows the image of serving a suffering friend as a hard bed.'),
     g('z-sign', 'После воспоминания о крике высших людей Заратустра называет сострадание последним искушением и противопоставляет поиску счастья своё дело.', 'After recalling the higher men’s cry, Zarathustra names fellow-suffering as his last temptation and contrasts his work with seeking happiness.')],
    b('Что связывает отвращение к возвращению малого с преодолением сострадания к высшим людям — один предмет оценки или изменение того, ради чего Заратустра действует?', 'What connects nausea at the small human’s return with overcoming pity for the higher men: one object of evaluation, or a change in what Zarathustra acts for?')),
  'demo:cosmological': q(
    b('У ворот Заратустра спрашивает, не должно ли всё способное произойти уже пройти по бесконечной дороге. Переход от бесконечного времени к повторению требует отдельного довода: последовательность может быть бесконечной в обоих направлениях и состоять из разных состояний. Ряд всех целых чисел показывает эту логическую возможность, сохраняя две неограниченные дороги вокруг выбранного нуля. Он позволяет точно выделить недостающий переход от бесконечности к возвращению, не выдавая условную модель за описание мира.', 'At the gateway, Zarathustra asks whether everything capable of happening must already have travelled the infinite path. Moving from infinite time to repetition needs a separate argument: a sequence can be infinite in both directions and consist of different states. The sequence of all integers shows this logical possibility while preserving two unbounded paths around a chosen zero. It isolates the missing transition from infinity to recurrence without presenting a hypothetical model as a description of the world.'),
    [g('z-vision', '§2: две бесконечные дороги и вопросы о том, что может и должно произойти, служат предметом логической реконструкции.', 'Section 2: two infinite paths and questions about what can and must happen are the object of logical reconstruction.')],
    b('Какая дополнительная посылка превращает бесконечность дороги в повторение её полного хода?', 'Which additional premise turns the path’s infinity into repetition of its complete course?'),
    { experiment: { setup: b('Рассмотрите условный ряд …, −2, −1, 0, 1, 2, … . От нуля он неограниченно продолжается в обе стороны, и каждое число встречается один раз.', 'Consider the hypothetical sequence …, −2, −1, 0, 1, 2, … . From zero it extends indefinitely in both directions, and each number occurs once.'), question: b('Какое условие, кроме бесконечности обеих дорог, должно исключить такую последовательность из довода о возвращении?', 'Which condition besides the infinity of both paths must exclude such a sequence from an argument for recurrence?') } }),

  'demo:existential': q(
    b('В §341 «Весёлой науки» демон описывает неизменное повторение, но дальнейший ход обращён к тому, что эта мысль сделает с адресатом. Между проклятием демона и признанием его божественным лежит вопрос о пережитом мгновении, способном изменить ответ. Затем повторение становится тяжестью, ложащейся на каждый поступок. Экзистенциальное прочтение прослеживает этот переход от сообщения о мире к преобразованию желания, сохраняя радикальность последнего вопроса — захотеть только такого окончательного подтверждения жизни.', 'In The Gay Science §341, the demon describes unaltered repetition, but the subsequent movement concerns what the thought will do to its addressee. Between cursing the demon and calling him divine stands the question of an experienced moment capable of changing the response. Repetition then becomes a weight placed on every action. An existential reading follows this transition from a statement about the world to a transformation of desire, preserving the final question’s radical demand: to want nothing but this ultimate confirmation of life.'),
    [g('gs341', 'После речи демона следуют два возможных ответа, вопрос о преображающей силе мысли и вопрос о желании её окончательного подтверждения.', 'The demon’s speech is followed by two possible responses, the thought’s power to transform, and the question of desiring its ultimate confirmation.')],
    b('Как меняется предмет §341 между первым сообщением демона и последним вопросом к адресату?', 'How does §341’s subject change between the demon’s initial announcement and the final question to the addressee?')),

  'demo:poetic': q(
    b('После вопросов о времени сцена пастуха переносит мысль из разговора в телесное событие. Заратустра пытается извлечь змею рукой, затем кричит об укусе и прерывает рассказ вопросами о видении и пастухе. Только после этих вопросов рассказ сообщает об укусе, преображении и смехе. Такое устройство удерживает загадку внутри действия: различие неудавшейся помощи и собственного укуса пастуха позволяет читать перемену как нечто большее, чем получение объяснения.', 'After the questions about time, the shepherd’s scene moves thought from conversation into a bodily event. Zarathustra tries to remove the snake by hand, then shouts for a bite and interrupts the account with questions about the vision and the shepherd. Only after these questions does the narrative report the bite, transformation and laughter. This arrangement holds the riddle within the action: the difference between failed assistance and the shepherd’s own bite allows the change to be read as more than receiving an explanation.'),
    [g('z-vision', '§2: неудача руки, призыв укусить, вопросы о видении и пастухе, затем укус, преображение и смех.', 'Section 2: the failed hand, the command to bite, questions about the vision and shepherd, then the bite, transformation and laughter.')],
    b('Какую часть этой последовательности теряет толкование, сводящее укус к простому получению верного тезиса?', 'Which part of this sequence is lost by interpreting the bite simply as receiving a correct thesis?')),

  'demo:temporal-knot': q(
    b('У ворот мгновение названо связанным со всеми вещами так, что оно влечёт за собой грядущее, включая себя. В «Об избавлении» предмет меняется: воля сталкивается с необратимостью бывшего и не может сделать его небывшим. Сопоставление различает связанность событий и работу воли над бывшим: образ узла не решает за неё задачу избавления. Поэтому общий вопрос о времени расходится на вопрос о ходе мира и вопрос о значении «я хотел этого».', 'At the gateway, the moment is described as connected with all things so that it draws the future after it, including itself. In “On Redemption”, the subject changes: the will confronts the irreversibility of what has been and cannot undo it. Comparison distinguishes events’ connectedness from the will’s work upon the past; the knot’s image does not accomplish redemption for it. The shared question of time thus divides into the world’s course and the meaning of “I willed this”.'),
    [g('z-vision', '§2: вопрос о связанности всех вещей и о том, что мгновение влечёт за собой.', 'Section 2: the question of all things being connected and what the moment draws after it.'), g('z-redemption', 'Плен воли перед бывшим и переход к требованию преобразовать «было» в воление.', 'The will’s captivity before what has been and the demand to transform “it was” into willing.')],
    b('Что объясняет связанность событий и чего она ещё не объясняет в требовании волить бывшее?', 'What does events’ connectedness explain, and what does it leave unexplained in the demand to will what has been?')),

  'demo:voice-reading': q(
    b('Звери не просто сообщают о возвращении: они воображают речь, которую Заратустра произнёс бы перед смертью. Первое лицо внутри этого предположения поэтому имеет два уровня: говорящих зверей и предполагаемого говорящего Заратустру. В конце герой занят разговором с душой и не слышит, как звери замолкают. Такое устройство позволяет различать изложение учения, присвоение голоса учителя и состояние самого учителя, не устраняя содержания сказанного.', 'The animals do more than state recurrence: they imagine a speech Zarathustra would deliver before death. The first person within that supposition therefore has two levels: the animals speaking and Zarathustra as the imagined speaker. At the end, the protagonist is occupied in conversation with his soul and does not hear the animals fall silent. This arrangement distinguishes an exposition of the teaching, an assumption of the teacher’s voice and the teacher’s own condition without removing what is said.'),
    [g('z-convalescent', '§2: звери предполагают предсмертную речь; после неё рассказчик описывает молчание Заратустры и его разговор с душой.', 'Section 2: the animals imagine a dying speech; afterwards the narrator describes Zarathustra’s silence and conversation with his soul.')],
    b('Что меняется в атрибуции формулы той же жизни, когда первое лицо прочитано внутри предположения зверей?', 'What changes in attributing the same-life formula when its first person is read within the animals’ supposition?')),

  'demo:performative': q(
    b('§341 прямо различает содержание мысли и её власть над тем, кто её мыслит. Демон сообщает одно и то же условие, но возможные ответы простираются от проклятия до высшего подтверждения. Далее вопрос о повторении сопровождает каждый поступок: мысль становится мерой желания действовать. Поэтому её действие не сводится к перемене настроения — меняется вес, который приобретает поступок в отношении целой жизни.', 'Section 341 explicitly distinguishes the thought’s content from its power over the thinker. The demon states the same condition, yet possible responses range from a curse to the highest confirmation. The question of repetition then accompanies every action: the thought becomes a measure of the desire to act. Its effect therefore exceeds a change of mood—the weight an action acquires in relation to the whole life changes.'),
    [g('gs341', 'Условное «если бы эта мысль овладела тобой» связывает возможность преображения или сокрушения с тяжестью вопроса для каждого действия.', 'The conditional “if this thought gained power over you” connects transformation or crushing with the question’s weight upon every action.')],
    b('Почему неизменность условия демона совместима с противоположными ответами и что тогда становится предметом испытания?', 'Why is the demon’s unchanging condition compatible with opposite responses, and what then becomes the object of the test?')),

  'demo:selective': q(
    b('Демон в §341 включает в возвращение каждую боль, радость и мельчайшую подробность в прежнем порядке. Поэтому выбор счастливого эпизода меняет не ответ на поставленное условие, а само условие. В четвёртой «Печати» утверждение изображено иначе: радость со скорбью и добро со злом смешиваются в одном сосуде. Сопоставление двух форм показывает переход от перечисления без исключений к образу единства, которое соединяет различное.', 'The demon in §341 includes every pain, joy and smallest detail in their former order. Selecting a happy episode therefore changes not the response to the stated condition but the condition itself. In the fourth “Seal”, affirmation takes another form: joy and sorrow, good and evil are mixed in one vessel. Comparing these forms reveals a movement from enumeration without exceptions to an image of unity joining what differs.'),
    [g('gs341', 'Речь демона исключает новое и сохраняет тот же порядок всего малого и великого.', 'The demon’s speech excludes novelty and preserves the same order of everything small and great.'), g('z-seven-seals', '§4: смешивание противоположностей и образ соли предшествуют признанию любви к вечности.', 'Section 4: the mixing of opposites and the salt image precede the declaration of love for eternity.')],
    b('Что образ смеси добавляет к строгому перечислению и почему его нельзя заменить удалением неприятных составляющих?', 'What does the mixture image add to strict enumeration, and why can it not be replaced by removing unwelcome ingredients?')),

  'demo:small-human': q(
    b('Заратустра объясняет своё отвращение не одним существованием зла. В его речи худшее необходимо для лучшего, но и лучший, и худший человек оказываются малы. Повтор малого означает, что жизнь не завершится однажды миром, в котором преодолённое навсегда исчезло. Трудность касается поэтому масштаба утверждения: способна ли мысль включить возвращение того, на преодоление чего направлено стремление?', 'Zarathustra does not explain his nausea merely by evil’s existence. In his speech the worst is necessary for the best, yet both the best and the worst human are small. The small human’s repetition means life will not culminate in a world from which what was overcome has vanished forever. The difficulty therefore concerns affirmation’s scope: can the thought include the return of what the striving aims to overcome?'),
    [g('z-convalescent', '§2: речь связывает худшее с лучшим, называет обоих малыми и возвращает отвращение к повтору малого человека.', 'Section 2: the speech connects the worst with the best, calls both small and traces nausea to the small human’s recurrence.')],
    b('Почему вечное возвращение малого затрудняет не только оценку прошлого, но и замысел преодоления?', 'Why does the small human’s eternal recurrence trouble not only an evaluation of the past but the project of overcoming?')),

  'demo:nonlinear': q(
    b('Сцена пастуха оставляет вопрос о его имени открытым. В «Выздоравливающем» Заратустра описывает собственное избавление от душившего чудовища языком укуса и отбрасывания. Позднее место позволяет вернуться к раннему и связать видение с испытанием того, кто его рассказывал. Но это движение понимания не требует считать все детали первой сцены уже окончательно расшифрованными.', 'The shepherd’s scene leaves his identity open. In “The Convalescent”, Zarathustra describes his own release from a choking monster in the language of biting and casting away. The later passage permits a return to the earlier one, connecting the vision with the ordeal of its narrator. Yet this movement of understanding does not require treating every detail of the first scene as definitively decoded.'),
    [g('z-vision', '§2: перед сообщением об укусе и преображении Заратустра спрашивает о видении и о том, кто пастух.', 'Section 2: before reporting the bite and transformation, Zarathustra asks about the vision and who the shepherd is.'), g('z-convalescent', '§2: Заратустра соотносит своё избавление с чудовищем, укусом и продолжающейся болезнью.', 'Section 2: Zarathustra relates his deliverance to the monster, the bite and his continuing illness.')],
    b('Какое отождествление теперь получает основание, а какие вопросы первой сцены остаются открытыми?', 'Which identification now gains grounds, and which questions of the first scene remain open?')),

  'demo:form-content': q(
    b('Речь у ворот движется вопросами, а не рядом завершённых доказательств. Заратустра наращивает их, затем становится тише и испытывает страх; ответ карлика о круге уже был отвергнут как слишком лёгкий. Если заменить вопросы уверенными утверждениями, исчезнет различие между предложенной необходимостью и её усвоением говорящим. Форма сцены показывает степень достигнутого понимания и путь, который мысль ещё должна пройти.', 'The gateway speech advances through questions rather than a series of completed proofs. Zarathustra accumulates them, then grows quieter and afraid; the dwarf’s answer about a circle has already been rebuked as too easy. Replacing questions with confident assertions removes the distinction between a proposed necessity and its appropriation by the speaker. The scene’s form shows the degree of understanding reached and the path thought still has to travel.'),
    [g('z-vision', '§2: упрёк карлику, последовательность вопросов и изменение голоса предшествуют смене сцены.', 'Section 2: the rebuke to the dwarf, the sequence of questions and the change in voice precede the scene’s transformation.')],
    b('Какие предпосылки пришлось бы явно доказать, если превратить вопросительную речь в теорему?', 'Which assumptions would need explicit proof if the interrogative speech were turned into a theorem?')),

  'demo:task': q(
    b('Первое нисхождение Заратустры начинается с избытка мудрости, которому нужны принимающие руки. Во «Выздоравливающем» положение меняется: звери называют его учителем возвращения и формулируют его судьбу перед ним самим. Между желанием одарить и назначением учителем возникает задача — не только произнести мысль, но и стать тем, чьё дело она определяет. Звери могут назвать эту задачу, однако молчание Заратустры оставляет её исполнение в движении книги.', 'Zarathustra’s first descent begins with an excess of wisdom needing receiving hands. In “The Convalescent”, the position changes: the animals name him the teacher of recurrence and formulate his destiny before him. Between the wish to bestow and the designation as teacher emerges a task—not only to state a thought but to become someone whose work it determines. The animals can name that task, while Zarathustra’s silence leaves its fulfilment within the book’s continuing movement.'),
    [g('z-prologue', '§1: избыток мудрости, потребность в руках и желание одарить мотивируют нисхождение.', 'Section 1: overflowing wisdom, the need for hands and the wish to bestow motivate the descent.'), g('z-convalescent', '§2: звери называют учительство возвращения судьбой Заратустры; глава завершается его молчанием.', 'Section 2: the animals call teaching recurrence Zarathustra’s destiny; the chapter ends in his silence.')],
    b('Чем различаются желание передать накопленное и принятие мысли как собственного дела?', 'How do the wish to transmit what has accumulated and taking a thought as one’s own work differ?')),

  'demo:open-reading': q(
    b('Упрёк зверям за шарманочный припев допускает разные вопросы: ошиблись ли они в содержании или сделали слишком лёгким способ его произнесения. Тот же разговор содержит строгую речь о возвращении каждой подробности и ответ Заратустры о его собственном отвращении. Сопоставление прочтений становится содержательным, когда каждое объясняет эти места вместе. Тогда выбор зависит от того, как связаны формула, голос и переживание, а не от простого числа подтверждающих строк.', 'The rebuke to the animals for their barrel-organ refrain allows different questions: is their content mistaken, or have they made its utterance too easy? The same conversation contains the strict speech about every detail returning and Zarathustra’s account of his nausea. Comparing readings becomes substantive when each explains these passages together. Preference then depends on how formula, voice and experience are connected rather than on counting supporting lines.'),
    [g('z-convalescent', '§2 соединяет упрёк зверям, объяснение отвращения и воображаемую ими речь о той же жизни.', 'Section 2 joins the rebuke to the animals, the explanation of nausea and their imagined speech about the same life.')],
    b('Какое место изменяет ваш ответ на вопрос, чему именно возражает Заратустра в речи зверей?', 'Which passage changes your answer to what exactly Zarathustra objects to in the animals’ speech?')),

  'demo:lived-rhythm': q(
    b('Во «Выздоравливающем» круговорот сначала звучит как лёгкая песня зверей, на которую Заратустра отвечает упрёком в шарманочности. Позднее сами звери предлагают ему новые песни для новых лир и называют пение подходящим выздоравливающему. Значит, различие проходит не просто между повтором и новизной или между речью и музыкой. Исследовать ритм здесь — значит выяснять, как повторяемая форма связана с состоянием того, кто её произносит и слышит.', 'In “The Convalescent”, circular movement first sounds as the animals’ easy song, answered by Zarathustra’s barrel-organ rebuke. Later the animals themselves propose new songs for new lyres and call singing appropriate to a convalescent. The distinction therefore does not fall simply between repetition and novelty or between speech and music. Investigating rhythm here means asking how a repeated form is connected with the condition of its speaker and listener.'),
    [g('z-convalescent', '§2: повторяющаяся песня, упрёк в шарманочности и последующий совет новых песен для новых лир дают разные функции звучащего повтора.', 'Section 2: the repeated song, barrel-organ rebuke and later advice of new songs for new lyres give sounding repetition different functions.')],
    b('Почему песня может в одной части разговора упрощать мысль, а в другой сопровождать выздоровление?', 'Why can song simplify the thought in one part of the conversation and accompany convalescence in another?')),

  'demo:return-practice': q(
    b('Повторное чтение позволяет проверить связь двух сцен на неизменившихся словах. Если после «Выздоравливающего» пастух начинает напоминать самого Заратустру, основанием служит позднейший рассказ об укусе чудовища. Но в первой сцене остаются крик, неудача руки и вопросы об имени пастуха. Практика возвращения поэтому сопоставляет приобретённое основание с тем, что оно ещё не объяснило.', 'Rereading allows the connection between two scenes to be examined against unchanged words. If the shepherd begins to resemble Zarathustra himself after “The Convalescent”, the ground is the later account of biting the monster. Yet the first scene still contains the shout, the failed hand and the questions about the shepherd’s identity. The practice of returning therefore compares a newly acquired ground with what it has not yet explained.'),
    [g('z-vision', '§2: первая последовательность удушья, укуса и преображения.', 'Section 2: the first sequence of choking, biting and transformation.'), g('z-convalescent', '§2: Заратустра рассказывает о своём освобождении через образ укуса чудовища.', 'Section 2: Zarathustra recounts his deliverance through the image of biting the monster.')],
    null,
    { experiment: { setup: b('Прочитайте сцену пастуха до и после рассказа Заратустры о чудовище. Назовите одну связь, ставшую обоснованнее, и одну деталь, которая всё ещё требует объяснения.', 'Read the shepherd’s scene before and after Zarathustra’s account of the monster. Name one connection that has gained grounds and one detail that still requires explanation.'), question: b('Чем второе чтение изменило именно довод, а не только впечатление знакомости?', 'How did the second reading change the argument itself rather than merely the impression of familiarity?') } }),
  'demo:fatalism': q(
    b('Вопрос о бездействии требует различить зависимость поступка от причин и отсутствие у него действия на происходящее. В доказательстве conatus единичная вещь выражает определённую силу именно как то, что существует и действует; зависимость её природы не превращает её в отсутствие силы. У Эпиктета же работа над собственным суждением остаётся задачей при исключении тела, имущества и должности из собственного. Эти два входа по-разному сохраняют действие внутри ограничения, не обещая независимости от всего остального.', 'The question of inaction requires distinguishing an action’s dependence on causes from its having no effect on what happens. In the conatus proof, an individual thing expresses a determinate power precisely as something existing and acting; the dependence of its nature does not turn it into an absence of power. For Epictetus, working upon one’s judgment remains a task while body, property and office are excluded from one’s own. These entries preserve action within limitation in different ways without promising independence from everything else.'),
    [g('spinoza3p6', 'Доказательство выводит стремление вещи из определённого выражения силы, посредством которой Бог существует и действует.', 'The proof derives a thing’s striving from a determinate expression of the power whereby God exists and acts.'), g('epictetus1', 'Разделение собственного и внешнего завершается предписанием рассматривать каждое суровое впечатление.', 'The division of one’s own and the external ends with an instruction to examine each harsh impression.')],
    b('На каком дополнительном шаге признание зависимости стало бы утверждением, что собственное действие ничего не меняет?', 'At which additional step would acknowledging dependence become the claim that one’s own activity changes nothing?')),

  'demo:same-new': q(
    b('Речь демона в §341 исключает новое из повторяющейся жизни и сохраняет каждый её порядок и мысль. Однако внутри описанной жизни встреча с демоном сама остаётся встречей, вызывающей ещё не предрешённый для адресата ответ. Это различает новизну события для переживающего и отличие одного полного прохождения от другого. Добавление памяти о предыдущем цикле изменило бы условие, потому что в повторе должна сохраняться и последовательность мыслей.', 'The demon’s speech in §341 excludes novelty from the repeating life and preserves its order and every thought. Yet within the described life, meeting the demon remains an encounter calling forth a response not already settled for the addressee. This distinguishes an event’s novelty for the person experiencing it from a difference between complete passages. Adding memory of a preceding cycle would change the condition, since the sequence of thoughts must repeat too.'),
    [g('gs341', 'Демон прямо исключает новое и включает мысли в тот же ряд; последующие вопросы предлагают разные ответы адресата.', 'The demon explicitly excludes novelty and includes thoughts in the same sequence; subsequent questions propose different responses from the addressee.')],
    b('В каком смысле встреча может быть первой, если вся жизнь по условию уже повторяется?', 'In what sense can an encounter be first if the whole life is already repeating under the hypothesis?')),

  'demo:circle-change': q(
    b('Повтор полной последовательности не устраняет изменений внутри неё: повторяться может именно переход между различными состояниями. Речной фрагмент Гераклита позволяет отдельно увидеть сохранение реки при смене вод, а космический — порядок возгорания и угасания. Ни один из этих двух признаков сам по себе ещё не задаёт полный цикл. Поэтому сравнение различает изменение, сохраняющуюся связь и точное повторение всех состояний.', 'Repeating a complete sequence does not remove changes within it: what repeats may be the transition between different states. Heraclitus’s river fragment separately shows a river’s persistence through changing waters, while the cosmic fragment shows an order of kindling and quenching. Neither feature alone yet specifies a complete cycle. Comparison therefore distinguishes change, a persisting connection and exact repetition of every state.'),
    [g('heraclitus-river', 'B12 соединяет те же реки с приходом иных вод; это основание различить сохранение и неподвижность.', 'B12 joins the same rivers with the arrival of other waters, grounding a distinction between persistence and immobility.'), g('heraclitus-cosmos', 'B30 задаёт меры возгорания и угасания; полное возвращение состояния остаётся дополнительным вопросом.', 'B30 gives measures of kindling and quenching; complete recurrence of a state remains an additional question.')],
    b('Какое условие превращает упорядоченную смену состояний именно в замкнутую последовательность?', 'Which condition turns an ordered succession of states into a closed sequence?')),

  'demo:free-necessary': q(
    b('Если назвать несвободным всё необходимое, первое предложение спинозовского определения станет непонятным: свободная вещь существует именно необходимо. Различие проходит через источник определения — собственную природу либо другое. Поэтому для этого определения важно не отсутствие основания действия, а то, достаточно ли собственной природы для его определения. Вопрос о свободе внутри необходимости начинается с восстановления этой более строгой границы.', 'If everything necessary is called unfree, the first sentence of Spinoza’s definition becomes unintelligible: the free thing exists necessarily. The distinction concerns the source of determination—its own nature or another. For this definition, what matters is therefore not the absence of grounds for action but whether its own nature suffices to determine it. The question of freedom within necessity begins by recovering this stricter boundary.'),
    [g('spinoza1d7', 'I, определение 7: свободное определяется собой одним, принуждённое — другим к определённому способу существования и действия.', 'I, definition 7: what is free is determined by itself alone; what is constrained is determined by another to a definite mode of existence and action.'), g('epictetus1', 'Начало раздела отличает собственную деятельность от внешнего и называет свободными именно принадлежащие первой группе вещи; отсюда начинается сопоставление двух определений.', 'The section’s opening distinguishes one’s own activity from externals and calls the things in the first group free; comparison of the two definitions begins here.')],
    b('Что исключает выражение «собой одним», чего не исключало бы простое переживание собственного желания?', 'What does “by itself alone” exclude that merely experiencing one’s own desire would not?')),

  'demo:teach-live': q(
    b('Заратустра сам вызывает свою глубочайшую мысль, но встреча с ней заканчивается падением и семью днями болезни. После этого звери способны изложить возвращение легче, чем он способен о нём говорить. Разница между формулой и переживанием поэтому задана не обвинением учителя извне, а последовательностью самой главы. Название «выздоравливающий» удерживает понимание во времени: произнесённое учение ещё связано с преобразованием того, кто должен его нести.', 'Zarathustra summons his deepest thought himself, but the encounter ends in collapse and seven days of illness. Afterwards, the animals can expound recurrence more easily than he can speak of it. The difference between formula and experience is therefore given by the chapter’s own sequence rather than an external accusation against the teacher. The name “convalescent” keeps understanding within time: the stated teaching is still connected with the transformation of the one who must bear it.'),
    [g('z-convalescent', '§1: вызов мысли; начало §2: падение и семь дней болезни. Далее в §2 звери излагают учение, а Заратустра объясняет отвращение и остаётся выздоравливающим.', 'Section 1: the summons of thought; the beginning of section 2: collapse and seven days of illness. Later in section 2, the animals expound the teaching while Zarathustra explains his nausea and remains a convalescent.')],
    b('Что объясняет болезнь в движении главы, чего не объяснило бы простое незнание формулы?', 'What does illness explain in the chapter’s movement that merely not knowing the formula would not?')),

  'demo:human-overcoming': q(
    b('В трёх превращениях лев ещё не способен создать новые ценности: он завоёвывает свободу для нового созидания. Ребёнок вводит иной ход — начало, игру и утверждение, для которых одного отрицания недостаточно. Во «Выздоравливающем» возвращение малого осложняет представление о преодолении как окончательном исчезновении прежнего. Вместе эти места ставят вопрос о том, что меняется в созидающем, если преодолённое продолжает принадлежать целому возвращающейся жизни.', 'In the three metamorphoses, the lion cannot yet create new values: it wins freedom for new creation. The child introduces another movement—beginning, play and affirmation—for which negation alone is insufficient. In “The Convalescent”, the small human’s return complicates understanding overcoming as the final disappearance of what came before. Together these passages ask what changes in the creator if what has been overcome continues to belong to the whole of returning life.'),
    [g('z-metamorphoses', 'Лев может приобрести свободу для ценностей, но не создать их; ребёнку принадлежат новое начало и утверждение.', 'The lion can gain freedom for values but cannot create them; the child brings a new beginning and affirmation.'), g('z-convalescent', '§2: возвращение малого человека остаётся частью возвращения всего.', 'Section 2: the small human’s return remains part of everything returning.')],
    b('Почему завоевание свободы для созидания ещё не является самим созданием ценностей?', 'Why does winning freedom for creation not yet constitute creating values?')),

  'demo:proposition-poem': q(
    b('Космологический довод можно реконструировать из вопросов у ворот, но такая реконструкция объясняет только часть движения главы. Упрёк карлику касается лёгкости ответа, а сцена пастуха переносит загадку в удушье, укус и смех. Поэтическая форма не отменяет вопроса о предпосылках: она добавляет вопрос о том, как мысль становится испытанием. Поэтому тезис и сцена могут исследоваться вместе без превращения каждого образа в отдельное доказательство.', 'A cosmological argument can be reconstructed from the gateway questions, but that reconstruction explains only part of the chapter’s movement. The rebuke to the dwarf concerns his answer’s ease, while the shepherd’s scene moves the riddle into choking, biting and laughter. Poetic form does not remove the question of assumptions: it adds the question of how a thought becomes an ordeal. Thesis and scene can therefore be examined together without making each image a separate proof.'),
    [g('z-vision', '§2 соединяет круг карлика, вопросы Заратустры и загадку пастуха в одной повествовательной последовательности.', 'Section 2 joins the dwarf’s circle, Zarathustra’s questions and the shepherd’s riddle in one narrative sequence.')],
    b('Как меняется задача читателя при переходе от ворот к пастуху?', 'How does the reader’s task change in the transition from the gateway to the shepherd?')),

  'demo:character-author': q(
    b('В «Об избавлении» Заратустра меняет адресата: ответ горбуну сменяется речью ученикам, а конец снова возвращает голос горбуну. Тот замечает различие между речью к народу, ученикам и себе. Поэтому позицию произведения нельзя восстановить одним изъятием торжественной формулы: сама смена речи становится предметом вопроса. Различение автора и персонажа здесь начинается с устроенного автором отношения голосов, а не с предположения, что ни один голос ничего не утверждает.', 'In “On Redemption”, Zarathustra changes addressee: his answer to the hunchback gives way to a speech to the disciples, and the ending returns the voice to the hunchback. The latter notices differences between speech to the people, to disciples and to oneself. The work’s position therefore cannot be reconstructed simply by extracting a solemn formula: the change in speech itself becomes a question. Distinguishing author and character here begins with the author’s arrangement of voices, not the assumption that no voice asserts anything.'),
    [g('z-redemption', 'Начальный разговор с горбуном, обращение к ученикам и заключительный вопрос горбуна о разных речах.', 'The opening conversation with the hunchback, the address to disciples and the hunchback’s concluding question about different speeches.')],
    b('Что позволяет объяснить смена адресата, чего не видно в отдельно выписанной формуле об избавлении?', 'What does the change of addressee explain that is invisible in an isolated formula about redemption?')),

  'demo:again-memory': q(
    b('В §341 повтор охватывает мысли так же, как боли, радости и события. Если во втором прохождении появляется дополнительное воспоминание о первом, последовательность мыслей уже отличается. Ощущение знакомости, напротив, могло бы входить в обе одинаковые жизни и потому не удостоверяло бы переход между ними. Так вопрос об узнавании отделяет условие полного повтора от возможного свидетельства о нём.', 'In §341, repetition includes thoughts just as it includes pains, joys and events. If an additional memory of the first passage appears in the second, the sequence of thoughts already differs. A feeling of familiarity, by contrast, could belong to both identical lives and would therefore not establish a passage between them. The question of recognition thus separates the condition of complete repetition from possible evidence of it.'),
    [g('gs341', 'Демон включает каждый помысел и самого себя в неизменный ряд возвращающегося; рассуждение о памяти выводит следствие этого условия.', 'The demon includes every thought and himself in the unchanging returning sequence; the discussion of memory draws out a consequence of that condition.')],
    b('Как должна быть устроена память, чтобы сохраниться в строгом повторе и не добавить к нему нового события?', 'How must memory be constituted to remain within strict repetition without adding a new event to it?')),

  'demo:whole-part': q(
    b('Заратустра спрашивает, не связаны ли все вещи так, что мгновение влечёт за собой всё грядущее и само себя. В §341 та же полнота выражается через перечисление малого и великого в прежнем порядке. Сопоставление различает два довода о целом: связанность событий и условие тождества всей последовательности. Изменение одной подробности нарушает второе условие, но само по себе ещё не показывает, какие именно причинные связи нарушены в первом.', 'Zarathustra asks whether all things are so connected that the moment draws all the future after it, including itself. In §341, the same completeness is expressed by enumerating the small and great in their former order. Comparison distinguishes two arguments about a whole: events’ connectedness and the condition of an entire sequence’s identity. Changing one detail violates the second condition without yet showing which causal connections are broken in the first.'),
    [g('z-vision', '§2: вопрос о связанности всех вещей связывает мгновение и грядущее.', 'Section 2: the question of all things being connected joins the moment to what is coming.'), g('gs341', 'Полный прежний порядок — прямо сформулированное условие демона.', 'The entire former sequence is an explicit condition of the demon’s speech.')],
    b('Какой вид связи вы утверждаете, говоря, что без одного мгновения не было бы всей этой жизни?', 'Which kind of connection are you asserting when saying that without one moment this whole life would not exist?')),

  'demo:cosmos-evidence': q(
    b('Вопросы у ворот подводят к всеобщему утверждению о повторе, но не представляют собой наблюдение нескольких мировых циклов. Для оценки космологического прочтения важно различить основание, заданное моделью, и основание, полученное из наблюдения. Конечное число замеченных повторов не исключает дальнейшего отличия, как и сходство не устанавливает полного тождества. Поэтому исследование ищет посылку, которая связывает доступное описание со всеобщим выводом.', 'The gateway questions approach a universal claim about recurrence, but they are not an observation of several world cycles. Assessing a cosmological reading requires distinguishing grounds supplied by a model from grounds obtained through observation. Finitely many observed repetitions do not exclude a later difference, just as resemblance does not establish complete identity. Inquiry therefore seeks the premise connecting the available description with a universal conclusion.'),
    [g('z-vision', '§2: бесконечные дороги и вопросы о возможном/необходимом дают именно рассуждение для реконструкции, а не отчёт о наблюдавшихся циклах.', 'Section 2: infinite paths and questions about possibility and necessity provide reasoning to reconstruct rather than a report of observed cycles.')],
    b('Что могло бы обосновать переход от сходных событий к возвращению всех событий в том же порядке?', 'What could ground the transition from similar events to all events returning in the same order?')),

  'demo:decision': q(
    b('В §341 мысль о повторе должна лечь тяжестью на каждый поступок. Будущий повтор здесь не предлагается как новая попытка исправить результат: он сохраняет тот же поступок в прежнем ряду. Поэтому решение получает иной горизонт — желание его бесчисленного возвращения вместе с целой жизнью. Это позволяет исследовать действие через его связь с подтверждением жизни, не подменяя вопрос выбором улучшенной следующей версии.', 'In §341, the thought of recurrence is to weigh upon every action. Future recurrence is not offered as another attempt to correct the result: it retains the same act in the former sequence. A decision therefore acquires another horizon—the desire for its countless returns together with the whole life. This allows action to be examined through its connection with confirming life without replacing the question with choosing an improved next version.'),
    [g('gs341', 'Вопрос «хочешь ли ещё раз» относится ко всему и каждому поступку, при уже установленном отсутствии нового.', 'The question of wanting it again applies to everything and every action, with novelty already excluded.')],
    b('Как меняется оценка поступка, если следующего возвращения нельзя использовать для его исправления?', 'How does evaluating an action change if the next return cannot be used to correct it?')),

  'demo:responsibility': q(
    b('Эпиктет связывает обвинение богов и людей с присвоением того, что не принадлежит собственному действию. В «Об избавлении» Заратустра иначе объясняет обращение к наказанию: воля мстит за свою неспособность сделать бывшее небывшим. Сопоставление исследует две причины обвиняющего отношения — ошибку в границе собственного и бессилие перед временем. Оно не даёт единой теории распределения вины, а позволяет точнее поставить вопрос, от какого отношения каждый текст ищет освобождения.', 'Epictetus connects blaming gods and people with claiming what does not belong to one’s own activity. In “On Redemption”, Zarathustra explains the turn to punishment differently: the will takes revenge for its inability to undo what has been. Comparison examines two sources of an accusatory relation—a mistake about the boundary of one’s own and powerlessness before time. It supplies no unified theory of allocating blame, but sharpens the question of which relation each text seeks release from.'),
    [g('epictetus1', 'Принимающий чужое за своё оказывается стеснённым и обвиняет богов и людей; противоположный ход снимает обвинение.', 'Taking what belongs to others as one’s own leads to constraint and blame against gods and people; the opposite movement removes accusation.'), g('z-redemption', 'Воля не может волить назад; её неприязнь к бывшему разворачивается в месть и язык наказания.', 'The will cannot will backwards; its aversion to what has been develops into revenge and the language of punishment.')],
    b('Почему отказ от обвинения в одном тексте требует различить своё и чужое, а в другом — преобразовать отношение к бывшему?', 'Why does leaving accusation behind require distinguishing one’s own from another’s in one text, and transforming the relation to what has been in the other?')),

  'demo:shared-world': q(
    b('Марк Аврелий выводит полезное для себя из разумной и общественной природы и принадлежности двум городам — Риму и миру. В «О сострадательных» связь с другим разбирается иначе: через дар, стыд принимающего и любовь, стремящуюся создать любимое. Эти места задают разные основания совместности: принадлежность целому и определённый способ одаривать и любить. Сравнение спрашивает, что каждое основание делает существенным в отношении к другому, сохраняя различие исходных мер.', 'Marcus Aurelius derives what is useful to himself from rational and social nature and membership in two cities—Rome and the world. “The Pitiful” examines relation to another differently: through giving, the recipient’s shame and love seeking to create what is loved. These passages give different grounds for life with others: belonging to a whole and a particular way of bestowing and loving. Comparison asks what each ground makes significant in a relation to another while preserving the difference in their starting measures.'),
    [g('marcus6-44', 'Заключение VI.44 связывает пользу с разумной/общественной природой и двумя городами.', 'VI.44 concludes by linking usefulness with rational/social nature and two cities.'), g('z-pitiful', 'Помощь может уязвить гордость; дар друзьям и создающая любовь описаны через другие отношения, чем удовольствие от жалости.', 'Help can wound pride; giving to friends and creating love are described through relations different from pleasure in pity.')],
    b('Как различаются довод от общего города и довод от создающей любви, когда речь идёт о помощи?', 'How do an argument from the shared city and an argument from creating love differ when help is at issue?')),
  'demo:heraclitus': q(
    b('Фрагмент о реке удерживает вместе два определения: реки названы теми же, а воды — всё новыми. Отсюда можно поставить вопрос, чем сохраняется единство меняющегося, но нельзя сразу получить положение о возвращении всех состояний. Фрагмент о космосе добавляет другую связь: огонь живёт через мерное возгорание и угасание, а космос не создан ни богом, ни человеком. Сопоставление показывает, что постоянство порядка и перемена составляющего могут мыслиться совместно, ещё до вопроса о полном повторе.', 'The river fragment holds two determinations together: the rivers are called the same, while the waters are ever different. This raises the question of what preserves the unity of something changing, but does not immediately yield a claim that all states return. The cosmos fragment adds another connection: fire lives through measured kindling and extinction, and the cosmos was made by neither a god nor a human. Comparison shows that a continuing order and changing constituents can be thought together before the question of complete recurrence arises.'),
    [g('heraclitus-river', 'B12: свидетельство соединяет «те же реки» с притоком иных вод; окружающее рассуждение об испарении и душе принадлежит передающему свидетельству.', 'B12: the testimony joins “the same rivers” to incoming different waters; the surrounding discussion of exhalation and soul belongs to the transmitting witness.'), g('heraclitus-cosmos', 'B30: общий космос, отсутствие создания богом или человеком, вечноживой огонь и мера его изменений.', 'B30: the common cosmos, its not having been made by a god or human, ever-living fire and the measure of its changes.')],
    b('Что в каждом фрагменте сохраняет единство: прежний состав, имя целого или мера его изменения?', 'What preserves unity in each fragment: its former constituents, the whole’s name or the measure of its change?')),

  'demo:stoics': q(
    b('Первый раздел Эпиктета и VI.44 Марка Аврелия отвечают на разные вопросы о действии. Эпиктет выясняет, что принадлежит собственной деятельности и потому может быть предметом свободного суждения и желания. Марк Аврелий спрашивает, как определить полезное для себя при разных предположениях о божественном распоряжении. Его довод приходит к разумной и общественной природе и к двум городам — Риму и миру. Вместе тексты дают две точки входа: границу собственного и основание того, ради чего оно действует.', 'Epictetus’s first section and Marcus Aurelius VI.44 address different questions about action. Epictetus asks what belongs to one’s own activity and can therefore be the object of free judgment and desire. Marcus Aurelius asks how to determine what is useful to oneself under different suppositions about divine ordering. His argument arrives at rational and social nature and at two cities—Rome and the world. Together the texts provide two entrances: the boundary of one’s own and the ground of what it acts for.'),
    [g('epictetus1', 'Начальное различение собственного и внешнего ведёт к перемене притязаний и проверке впечатлений.', 'The opening distinction between one’s own and the external leads to changing claims and examining impressions.'), g('marcus6-44', 'Три предположения о богах завершаются доводом от собственной разумной/общественной природы и общего города.', 'Three suppositions about the gods conclude with an argument from one’s rational/social nature and the shared city.')],
    b('На какой вопрос отвечает граница собственного у Эпиктета и какой следующий вопрос открывает общественная природа у Марка Аврелия?', 'Which question does Epictetus’s boundary of one’s own answer, and which further question does Marcus Aurelius’s social nature open?')),

  'demo:providence': q(
    b('В VI.44 Марк Аврелий последовательно рассматривает распоряжение богов о нём самом, распоряжение только о целом и отсутствие распоряжения. Первое предполагает добрый замысел; второе связывает принятие случающегося с пользой целого. Третье он называет нечестивым предположением, но всё же продолжает рассуждение: сам человек способен определить полезное из своей природы. Разумная и общественная природа связывает эту пользу с городом. Поэтому ход фрагмента показывает не только веру в провидение, но и то, каким основанием действие располагает при переходе между предположениями.', 'In VI.44, Marcus Aurelius successively considers the gods’ ordering of his own life, their ordering only of the whole, and the absence of ordering. The first supposes a good design; the second connects accepting events with the whole’s benefit. He calls the third supposition impious, yet continues the reasoning: a person can determine what is useful from their own nature. Rational and social nature connects that usefulness with the city. The fragment’s movement therefore shows both belief in providence and the ground available to action as the suppositions change.'),
    [g('marcus6-44', 'VI.44 целиком: переходы «если обо мне», «если о целом», «если ни о чём», затем собственная природа и два города.', 'The whole of VI.44: transitions through “if about me”, “if about the whole” and “if about nothing”, followed by one’s nature and two cities.')],
    b('Какое основание полезного сохраняется в последней ветви рассуждения и от каких прежних предположений оно уже не зависит?', 'Which ground of usefulness remains in the argument’s last branch, and which earlier suppositions does it no longer depend on?')),

  'demo:conatus': q(
    b('В III, теореме 6, стремление сохранять своё существование относится к каждой вещи в пределах её силы. Доказательство выводит его из того, что вещи выражают божественную силу и противостоят собственному уничтожению. Теорема 7 отождествляет это стремление с действительной сущностью вещи; теорема 8 исключает из него заранее определённый конечный срок. Поэтому conatus обозначает сам способ действия существующего, а не добавленную к нему сознательную цель. Неопределённость срока также не исключает уничтожения внешней причиной.', 'In III, proposition 6, striving to preserve existence belongs to each thing as far as its power extends. The proof derives it from things expressing divine power and opposing their own destruction. Proposition 7 identifies this striving with the thing’s actual essence; proposition 8 excludes a predetermined finite duration from it. Conatus therefore names the existing thing’s very way of acting, rather than a conscious aim added to it. An indefinite duration also does not exclude destruction by an external cause.'),
    [g('spinoza3p6', 'III.6 и доказательство: стремление каждой вещи, мера её силы и противодействие тому, что отнимает существование.', 'III.6 and proof: each thing’s striving, the extent of its power and opposition to what removes its existence.'), g('spinoza3p7-8', 'III.7–8 с доказательствами: действительная сущность и неопределённая длительность, которая сохраняет возможность внешнего уничтожения.', 'III.7–8 with proofs: actual essence and indefinite duration, which leaves external destruction possible.')],
    b('Почему переход от «вещь стремится» к «стремление есть её сущность» меняет смысл стремления?', 'Why does the move from “a thing strives” to “striving is its essence” change the meaning of striving?')),

  'demo:leibniz': q(
    b('В §§53–55 «Монадологии» множество возможных универсумов ставит вопрос о достаточном основании существования одного из них. §54 связывает выбор со степенями совершенства, по которым возможное притязает на существование. §55 различает божественные мудрость, благость и могущество: лучшее познаётся, выбирается и производится. Так основание мира раскрывается через связку возможности и выбора, причём существование одного мира не устраняет мыслимость остальных.', 'In Monadology §§53–55, a plurality of possible universes raises the question of a sufficient reason for one of them to exist. Section 54 connects the choice with degrees of perfection through which possibilities lay claim to existence. Section 55 distinguishes divine wisdom, goodness and power: the best is known, chosen and produced. The world’s ground is thus unfolded through possibility and choice, while one world’s existence does not remove the thinkability of the others.'),
    [g('leibniz53-55', '§53 ставит вопрос об основании выбора; §54 задаёт степень совершенства; §55 распределяет познание, выбор и осуществление.', 'Section 53 raises the reason for choice; section 54 supplies degrees of perfection; section 55 distinguishes knowing, choosing and bringing about.')],
    b('Зачем §55 различает познание лучшего, его выбор и осуществление, если речь идёт об одном существующем мире?', 'Why does §55 distinguish knowing the best, choosing it and bringing it about when one existing world is at issue?')),

  'demo:possible-worlds': q(
    b('У Лейбница возможные миры входят в объяснение того, почему существует именно этот мир: различие возможностей предшествует вопросу об их выборе. У демона в §341 условие другое — прежняя жизнь возвращается без нового, со всеми подробностями в том же порядке. Поэтому другой возможный мир и ещё одно возвращение этой жизни различаются уже по постановке вопроса. Первый вводит альтернативу существующему; второе сохраняет существовавший ряд и спрашивает об отношении к его повтору.', 'For Leibniz, possible worlds enter the explanation of why this world exists: distinguishing possibilities precedes the question of their selection. The demon in §341 sets another condition—the former life returns without anything new, with every detail in the same order. Another possible world and another recurrence of this life therefore differ from the formulation of the question onward. The first introduces an alternative to what exists; the second preserves the former sequence and asks about one’s relation to its repetition.'),
    [g('leibniz53-55', 'Бесконечность возможных универсумов и существование одного требуют основания выбора.', 'Infinitely many possible universes and one existing universe require a reason for choice.'), g('gs341', 'Демон прямо исключает новое и сохраняет все подробности прежнего порядка.', 'The demon explicitly excludes novelty and retains every detail of the former sequence.')],
    b('Что меняется в вопросе о возвращении, если разрешить выбрать другую возможную жизнь?', 'What changes in the question of recurrence if choosing another possible life is allowed?')),

  'demo:kierkegaard': q(
    b('Первый абзац «Повторения» начинается с рассказа о Диогене, отвечающем на отрицание движения самой ходьбой. Константин Констанций затем предлагает поездку в Берлин, чтобы исследовать возможность повторения, и тут же вводит различие повторения и воспоминания. Понятие возникает между проверкой через действие и формулой движения вперёд и назад. Поскольку здесь говорит исследующий повествователь, начало следует читать как постановку опыта: оно ещё не сообщает его результата и не снимает трудности собственного определения.', 'Repetition’s first paragraph begins with Diogenes answering the denial of motion by walking. Constantin Constantius then proposes a journey to Berlin to investigate repetition’s possibility and immediately introduces the distinction between repetition and recollection. The concept emerges between a test through action and a formula of movement forwards and backwards. Since an investigating narrator speaks here, the opening should be read as setting up an inquiry: it has not yet reported its result or removed the difficulty of its own definition.'),
    [g('kierkegaard-repetition', 'Первый абзац: Диоген, замысел возвращения в Берлин, аналогия с греческим воспоминанием и противоположные направления движения.', 'The first paragraph: Diogenes, the proposed return to Berlin, the analogy with Greek recollection and the opposite directions of movement.')],
    b('Что добавляет замысел поездки к определению повторения, данному в том же абзаце?', 'What does the proposed journey add to the definition of repetition given in the same paragraph?')),

  'demo:repetition': q(
    b('Константин Констанций называет повторение и воспоминание одним движением в противоположных направлениях. Уже бывшее вспоминается назад, тогда как настоящее повторение должно вспоминаться вперёд. Затем он связывает возможное повторение со счастьем, а воспоминание — с несчастьем, добавляя условие: человек должен дать себе время пожить. Образ попытки ускользнуть из жизни в самый миг рождения, сославшись на забытое, возвращает формулу направлений к вопросу о том, останется ли движение внутри жизни.', 'Constantin Constantius calls repetition and recollection the same movement in opposite directions. What has been is recollected backwards, whereas genuine repetition is to recollect forwards. He then connects possible repetition with happiness and recollection with unhappiness, adding a condition: a person must give themselves time to live. The image of trying to slip out of life at the very moment of birth, pleading something forgotten, returns the formula of directions to the question of whether movement will remain within life.'),
    [g('kierkegaard-repetition', 'Вторая половина первого абзаца: противоположные направления, «вперёд» в определении повторения и оговорка о времени жить.', 'The second half of the opening paragraph: opposite directions, “forwards” in repetition’s definition and the qualification about taking time to live.')],
    b('Почему «вспоминать вперёд» труднее понять, чем просто снова оказаться в прежнем месте?', 'Why is “recollecting forwards” harder to understand than simply being in the former place again?')),

  'demo:camus': q(
    b('В заключительном разделе «Мифа о Сизифе» решающее внимание переносится с подъёма камня на спуск. В промежутке герой знает собственное положение, и именно сознание придаёт мифу трагический смысл. Затем Камю показывает возможность другой оценки того же удела: память связывает поступки в принадлежащую человеку судьбу, а отсутствие высшего хозяина меняет отношение к миру. Заключительное счастье возникает из этого движения ясности и присвоения судьбы при продолжающемся труде.', 'In the concluding section of The Myth of Sisyphus, decisive attention moves from raising the stone to the descent. In the interval, the hero knows his condition, and consciousness gives the myth its tragic meaning. Camus then shows another possible evaluation of the same lot: memory connects actions into a fate belonging to the person, while the absence of a higher master changes the relation to the world. The concluding happiness arises from this movement of lucidity and making fate one’s own while the labour continues.'),
    [g('camus-sisyphus', 'Заключительный раздел: спуск как время сознания, трагичность знания, память о своих действиях и последние абзацы о принадлежащем человеку уделе.', 'The concluding section: descent as the time of consciousness, the tragedy of knowing, memory of one’s actions and the final paragraphs on a fate belonging to the person.')],
    b('Почему Камю помещает перемену отношения к уделу именно во время спуска, когда камень уже снова внизу?', 'Why does Camus place the change in relation to fate during the descent, when the stone is already below again?')),

  'demo:sisyphus': q(
    b('Повтор труда у Камю делает возможным возвращающийся промежуток сознания. Спуск может сопровождаться скорбью, но Камю не закрепляет за ним единственного чувства: тот же путь становится местом ясности и радости. Камень остаётся предметом труда, однако его оценка меняется вместе с отношением к судьбе и богам. Поэтому заключительный образ счастья связан с устойчивым усилием и сознанием своего удела, а не с воображаемым последним подъёмом, после которого задача исчезнет.', 'The recurrence of labour in Camus makes a returning interval of consciousness possible. Descent can be accompanied by sorrow, but Camus does not assign it a single feeling: the same path becomes a place of lucidity and joy. The stone remains the object of labour, yet its evaluation changes with the relation to fate and the gods. The concluding image of happiness is therefore connected with continuing effort and awareness of one’s lot, rather than an imagined final ascent after which the task disappears.'),
    [g('camus-sisyphus', 'Заключительный раздел соединяет повтор спуска, возможность скорби и радости и неизменное продолжение подъёма в конце.', 'The concluding section connects recurring descent, the possibility of sorrow and joy, and the unchanged continuation of ascent at the end.')],
    b('Что должно измениться для заключительного счастья, если ни тяжесть камня, ни повтор труда не исчезают?', 'What must change for the concluding happiness if neither the stone’s weight nor recurring labour disappears?')),

  'demo:deleuze': q(
    b('Во введении к «Различию и повторению» Делёз отделяет повторение от общности закона и узнаваемой одинаковости случаев. Сопоставляя Кьеркегора и Ницше, он находит движение, которое должно совершаться в самой мысли, а не только представляться ею. При этом различие Бога у первого и Диониса у второго названо непреодолимым. Возвращение в ницшеанской линии Делёз описывает как силу отбора: оно изгоняет и создаёт, разрушает и производит. Так повторение становится вопросом о преобразующем движении, которому внешнего сходства недостаточно.', 'In the introduction to Difference and Repetition, Deleuze separates repetition from the generality of law and the recognisable sameness of cases. Comparing Kierkegaard and Nietzsche, he finds a movement that must take place within thought rather than merely be represented by it. Yet he calls the difference between the first thinker’s God and the second’s Dionysus insurmountable. In the Nietzschean line, Deleuze describes recurrence as a power of selection: it expels and creates, destroys and produces. Repetition thus becomes a question of transformative movement for which outward resemblance is insufficient.'),
    [g('deleuze-repetition', 'Введение, печатные с. 4–11: повторение против общности природного/морального закона; театр движения; непреодолимое различие Бога и Диониса; отбирающее возвращение.', 'Introduction, printed pp. 4–11: repetition against the generality of natural/moral law; the theatre of movement; the insurmountable difference between God and Dionysus; selective recurrence.')],
    b('Почему для Делёза изображение движения ещё не совершает того движения, которое он ищет в повторении?', 'Why, for Deleuze, does representing movement not yet perform the movement he seeks in repetition?')),

  'demo:return-difference': q(
    b('Делёз читает упрёки Заратустры карлику и зверям как исправление понимания возвращения через круг и тождество. Во введении к «Различию и повторению» повторение обладает силой отбора, а не просто вновь предъявляет одинаковое. Это определённая интерпретация ницшеанских сцен: она связывает упрёк с содержанием ответа, затем раскрывает возвращение как созидание и разрушение. Дальнейшая речь зверей о той же жизни создаёт точную задачу для сравнения: нужно объяснить, как её содержание связано с упрёком шарманке и с продолжающимся выздоровлением Заратустры.', 'Deleuze reads Zarathustra’s rebukes to the dwarf and the animals as correcting an understanding of recurrence through circularity and identity. In the introduction to Difference and Repetition, repetition has a power of selection rather than simply presenting the identical again. This is a definite interpretation of the Nietzschean scenes: it connects the rebuke with the answer’s content and then unfolds recurrence as creation and destruction. The animals’ later speech about the same life creates a precise task for comparison: explaining how its content relates to the barrel-organ rebuke and Zarathustra’s continuing convalescence.'),
    [g('deleuze-repetition', 'Введение, с. 6–11: Делёз связывает поправки карлику/зверям с недостаточностью кругового закона и приписывает возвращению отбор.', 'Introduction, pp. 6–11: Deleuze connects the corrections to the dwarf/animals with the insufficiency of circular law and attributes selection to recurrence.'), g('z-vision', '§2: Заратустра отвечает на круг карлика упрёком в чрезмерной лёгкости.', 'Section 2: Zarathustra answers the dwarf’s circle with a rebuke about making it too easy.'), g('z-convalescent', '§2: упрёк шарманке сосуществует с дальнейшей речью зверей об этой же жизни во всех подробностях.', 'Section 2: the rebuke to barrel-organ speech coexists with the animals’ later account of this very life in every detail.')],
    b('Какие подробности сцен позволяют решить, исправляет ли Заратустра содержание ответа, способ произнесения или оба сразу?', 'Which details of the scenes help determine whether Zarathustra corrects the answer’s content, its manner of utterance or both?')),
};
